class TFMLogicComponentDimensions extends TFMLogicComponent
{
    boolean disableProdDim, disableStorDim, disableTracDim;
}

Method.Source:
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    if (!disableStorDim)
    {
        // Warehouse to count
        refCon.addCollector(TFMGetReferenceData::createDefaultWarehouseReferenceData(1, strLwr(extendedTypeStr(InventLocationId)), "@SYS6437", methodStr(TFMGetReferenceData,WarehouseList)));
    }
    // Item number text box
    refCon.addCollector(TFMGetReferenceData::defaultItemIdCollector(40));
    return refCon;
}

public boolean parmDisableProductDim(boolean _disableProdDim = disableProdDim)
{
    disableProdDim = _disableProdDim;
    return disableProdDim;
}

public boolean parmDisableStorageDim(boolean _disableStorDim = disableStorDim)
{
    disableStorDim = _disableStorDim;
    return disableStorDim;
}

public boolean parmDisableTrackingDim(boolean _disableTracDim = disableTracDim)
{
    disableTracDim = _disableTracDim;
    return disableTracDim;
}

[TFMOrderPostDataSet(tableStr(inventDim))]
public InventDim getInventDim(TFMRequestElement _request)
{
    InventDim inventDim;
    //Find inventDim from request


    return inventDim;
}

/// <summary>
/// Method that tells which request Class it's data can be parsed into
/// </summary>
/// <returns>The name of the request class the components data can be parsed to</returns>
public ClassName requestClassProvided()
{
    return classStr(TFMRequestItemAndDimensionElement);
}

public TFMRegistrationCollectors registrationCollectors()
{
    return TFMInventDimHelper::enabledInventDimCollectors('',disableProdDim, disableStorDim, disableTracDim);
}

public TFMRequestElement componentRequest(TFMRequestElement _request)
{
    TFMRequestElement locRequest = super(_request);
    locRequest.logicContext().addContextObject(TFMLogicContextDimensionSetup::Construct());

    return locRequest;
}
